static void vDagKickoffTask(void* pvParameters) {
  (void)pvParameters;
  vDagSubmitInitialNodes();
  vTaskDelete(NULL);
}

void vStartDagDemo(void) {
  /* Allow runtime overrides for worker count and CU availability. */
  extern UBaseType_t gDagWorkerCountOverride;
  extern uint32_t gCuAvailableCount; /* from cu_offload.c */

  vDagInit(); vCuInit();

  /* tell runtime how many nodes exist so we can time completion */
  vDagSetTotalNodes(512U);

  UBaseType_t workers = (gDagWorkerCountOverride != 0u) ? gDagWorkerCountOverride : (UBaseType_t)NUM_WORKERS;
  DagRuntimeConfig cfg = { .workerCount = workers, .workerPriority = tskIDLE_PRIORITY + 2,
    .workerStackWords = 512, .asyncPriority = tskIDLE_PRIORITY + 3, .asyncStackWords = 512,
    .readyQueueLen = DAG_QUEUE_LEN, .asyncDoneQueueLen = DAG_ASYNC_DONE_QUEUE_LEN, .useCoreAffinity = 1 };

  /* Apply CU availability override if set */
  if (gCuAvailableCount != 0u) {
    vCuSetAvailableCount(gCuAvailableCount);
  }

  vDagRuntimeStart(&cfg);
  configASSERT(xTaskCreate(vDagKickoffTask, "DagKick", 512, NULL,
                           tskIDLE_PRIORITY + 1, NULL) == pdPASS);
}
